  ('sovietski-rusalka-superheavy-machine', 'Head', 80, '+80 from the exterior helmet. Small target: Called Shot only, -3 to strike. Destroying the head kills the character.', 10),
  ('sovietski-rusalka-superheavy-machine', 'Main Body', 260, '+240 for Heavy Rusalka Cyborg Armor. Depleted, the body is destroyed but life support keeps the brain alive up to 36 hours for recovery and a new body; 125 points below zero destroys the cyborg beyond recovery.', 11),
  ('sovietski-thunderfist-superheavy-machine', 'Hands (4)', 50, 'Each. Small target: Called Shot only, -3 to strike.', 1),
  ('sovietski-thunderfist-superheavy-machine', 'Arms (4; first entry)', 150, 'Each. The M.D.C. table prints Arms (4) twice, at 150 and at 210 each, without saying which pair is which; the text calls the upper pair oversized.', 2),
  ('sovietski-thunderfist-superheavy-machine', 'Vibro-Chainsaws (2; left forearms)', 50, 'Each. Small target: Called Shot only, -3 to strike.', 3),
  ('sovietski-thunderfist-superheavy-machine', 'Forearm Ion Blasters (2; right forearms)', 25, 'Each. Small target: Called Shot only, -3 to strike.', 4),
  ('sovietski-thunderfist-superheavy-machine', 'Arms (4; second entry)', 210, 'Each. The second of the two Arms (4) lines the M.D.C. table prints.', 5),
  ('sovietski-thunderfist-superheavy-machine', 'Legs (2)', 200, 'Each.', 6),
  ('sovietski-thunderfist-superheavy-machine', 'Feet (2)', 65, 'Each.', 7),
  ('sovietski-thunderfist-superheavy-machine', 'Shoulder Grenade Launcher (1; right)', 50, 'Small target: Called Shot only, -3 to strike.', 8),
  ('sovietski-thunderfist-superheavy-machine', 'Armored Head', 100, '+80 from the exterior helmet. Small target: Called Shot only, -3 to strike. Destroying the head kills the character.', 9),
  ('sovietski-thunderfist-superheavy-machine', 'Main Body', 580, 'Heavy armor plating is built in, so no further armor can be added. Depleted, the body is destroyed but life support keeps the brain alive up to 36 hours for recovery and a new body; 125 points below zero destroys the cyborg beyond recovery.', 10);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sovietski-rusalka-superheavy-machine', 1, 'Combat Tentacles (4)', '1D4 M.D. restrained punch or tentacle whip, 2D4 M.D. full strength, 4D4 M.D. power punch or whip (counts as two melee attacks)', 1, 'Melee: the arms reach 3 feet (0.9 m), the tentacles up to 12 feet (3.7 m).', NULL, NULL, NULL, 'Close combat and boarding actions; they add attacks and let it climb. They retract to 8 feet (2.4 m) and extend to 12 feet (3.7 m). The weapon entry cites Robot P.S. 32, the attribute block 35.'),
  ('sovietski-rusalka-superheavy-machine', 2, 'Vibro-Harpoon (1; right forearm)', '1D6 M.D.; also usable to stab and slash in melee', 1, '50 feet (15.2 m)', 'Once, until retrieved.', 'One, with three spare harpoons carried on the back for reloading if the cable is cut.', '+1 to strike when fired and +10% to Climbing when used; -1 to strike and -1 to parry as a melee weapon.', 'Climbing and boarding. A forearm winch reels the cyborg up its cable to the embedded spike; pulling it free takes one melee action and resets it. Each 10 foot (3 m) length of cable has 15 M.D.C.; the item text also says 1D6+5 M.D. cuts it.'),
  ('sovietski-rusalka-superheavy-machine', 3, 'Extendible Forearm Vibro-Sword (1; left)', '3D6 M.D. per strike (Robot P.S. damage included)', 1, 'Melee combat.', NULL, 'Effectively unlimited.', NULL, 'Extends and retracts at will; also used to cut cables, the harpoon line included.'),
  ('sovietski-rusalka-superheavy-machine', 4, 'Palm Blue-Green Laser Blasters (2)', '2D6 M.D. per blast', 1, '1,000 feet (305 m)', 'Each shot counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Assault. One in each palm, also used for spot welding.'),
  ('sovietski-thunderfist-superheavy-machine', 1, 'Thunderfist Knuckle Bulletdusters (4)', '1D6 M.D. per barrel; normally all three fire as a punch lands, 3D6 M.D. on top of the 2D6 M.D. punch for 5D6 M.D. per enhanced punch. Silver or wood slugs do double damage to creatures vulnerable to them.', 1, 'Punches with a 7 foot (2.1 m) reach, or fired up to 90 feet (27.4 m).', 'One barrel or all three at once, as many times as the character''s hand to hand attacks.', '30 rounds per fist magazine, enough for 30 full-damage punches.', '-4 to strike when fired as a ranged weapon.', 'Melee combat. Triple-barreled, one in each fist, set off by a pressure sensor on impact unless the cyborg overrides it; light explosive rounds. 22,000 credits buys the first weapon with its ammo feed, 11,000 each further barrel; ammunition 75 credits a round. Needs a full bionic hand and arm and counts as one forearm weapon.'),
  ('sovietski-thunderfist-superheavy-machine', 2, 'Shoulder-Mounted Grenade Launcher (1; right)', '4D6 M.D. to everything in a 3 foot (0.9 m) radius per shot', 1, '1,000 feet (305 m)', 'Single shots only.', 'Six grenades, or belt-fed from a 50 grenade drum carried on the back.', NULL, 'Anti-personnel and anti-armor. Mounted above the right shoulder.'),
  ('sovietski-thunderfist-superheavy-machine', 3, 'Palm Ion Blasters (2)', '3D6 M.D. per blast', 1, '300 feet (91.4 m)', 'Each blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'One in each upper-arm palm, for single soldiers at close range. The entry prints two primary purposes, Assault and Defense.'),
  ('sovietski-thunderfist-superheavy-machine', 4, 'Forearm Ion Blasters (2)', '4D6 M.D. per single blast', 1, '1,000 feet (305 m)', 'Each blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Defense. A low-profile blaster in each of the two right forearms.'),
  ('sovietski-thunderfist-superheavy-machine', 5, 'Mega-Damage Chainsaws (2)', '5D6 M.D. per slash, or 5D6 M.D. per action in a sustained attack', 1, 'Hand to hand combat only.', NULL, NULL, '+1 to disarm, -1 to parry; W.P. Sword gives any further combat bonuses.', 'One in each of the two left forearms, extendible and retractable; cuts through body and vehicle armor, sensor arrays, fencing and doors.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sovietski-rusalka-superheavy-machine', 'sovietski-thunderfist-superheavy-machine');
SELECT 'their 21 locations are in' AS assertion, count(*) AS got, 21 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sovietski-rusalka-superheavy-machine', 'sovietski-thunderfist-superheavy-machine');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sovietski-rusalka-superheavy-machine', 'sovietski-thunderfist-superheavy-machine');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sovietski-rusalka-superheavy-machine', 'sovietski-thunderfist-superheavy-machine') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

